            'start': start,
            'end': reader.pos,
            'method': {'n': len(method), 'h': '%016x' % lit_hash(method)},
            'method_bytes': method,
            'target': {'n': len(target), 'h': '%016x' % lit_hash(target)},
            'target_bytes': target,
            'host': fingerprint_of(unique_host) if len(hosts) == 1 else EMPTY_FP,
            'host_bytes': unique_host,
            'host_count': len(hosts),
